            for (int j = 0; j < n; j++) {
                if (line.charAt(j) != 'Y' && line.charAt(j) != 'Z') {
                    n_rescue[i][j] += line.charAt(j) - '0';
                }
            }
        }

        for (int i = 0; i < N; i++) {
            Arrays.fill(infect_time[i], -1);
        }

        infect_time[explode[0]][explode[1]] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{explode[0], explode[1]});
        while (!q.isEmpty()) {
            int[] cell = q.poll();
            int i = cell[0], j = cell[1];
            for (int d = 0; d < 4; d++) {
                int ni = i + di[d], nj = j + dj[d];
                if (0 <= ni && ni < n && 0 <= nj && nj < n && g[ni].charAt(nj) == '.' && infect_time[ni][nj] == -1) {
                    infect_time[ni][nj] = infect_time[i][j] + 1;
